package com.jarvis.homemultitool;

import android.Manifest;
import android.app.Activity;
import android.app.role.RoleManager;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import android.view.*;

/** Premium settings screen: every action opens a real Android setting or performs a real JARVIS action. */
public class SettingsActivity extends Activity {
    private static final int BG=Color.rgb(2,6,10),SUR=Color.rgb(5,15,25),CYAN=Color.rgb(83,220,255),BORDER=Color.rgb(25,102,153),WHITE=Color.rgb(242,247,255),MUTED=Color.rgb(121,153,180),GREEN=Color.rgb(71,232,177),RED=Color.rgb(255,102,116),REQ=51;
    private TextView roleState,wakeState,micState,voiceState;private JarvisVoiceManager voice;
    private int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
    private TextView txt(String s,float sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(WHITE);v.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,sp);v.setIncludeFontPadding(false);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private GradientDrawable bg(int st,int fill,float r){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(r));if(st>0)g.setStroke(dp(1),st);return g;}
    private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}
    private TextView button(String s,View.OnClickListener c){TextView v=txt(s,13);v.setGravity(Gravity.CENTER);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setSingleLine(true);v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setPadding(dp(10),0,dp(10),0);v.setBackground(bg(BORDER,0xD9071420,18));v.setOnClickListener(c);return v;}
    private void immersive(){try{if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.hide(WindowInsets.Type.statusBars()|WindowInsets.Type.navigationBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else getWindow().getDecorView().setSystemUiVisibility(5894|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}catch(Throwable ignored){}}

    @Override protected void onCreate(Bundle b){super.onCreate(b);immersive();getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);voice=new JarvisVoiceManager(this);voice.init(this::refresh);build();}
    private void build(){
        ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);sc.setFillViewport(true);sc.setClipToPadding(false);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(9),dp(18),dp(32));
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView back=button("‹",v->finish());back.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,30);head.addView(back,new LinearLayout.LayoutParams(dp(50),dp(50)));TextView title=txt("J A R V I S",23);title.setGravity(Gravity.CENTER);title.setTextColor(CYAN);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setLetterSpacing(.17f);head.addView(title,new LinearLayout.LayoutParams(0,dp(50),1));TextView gear=button("⚙",v->open(Settings.ACTION_SETTINGS));gear.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,22);head.addView(gear,new LinearLayout.LayoutParams(dp(50),dp(50)));root.addView(head);
        TextView sub=txt("СИСТЕМА  •  ГОЛОС  •  ВЫЗОВ  •  ПРИВАТНОСТЬ",10);sub.setTextColor(MUTED);sub.setTypeface(Typeface.DEFAULT,Typeface.BOLD);sub.setLetterSpacing(.08f);root.addView(sub,lp(-1,22,2,6,0,8));

        section(root,"СИСТЕМНЫЙ АССИСТЕНТ");LinearLayout role=card();row(role,"JARVIS как помощник Android","Назначает JARVIS системным голосовым ассистентом. Это основной способ вызова JARVIS системной кнопкой помощника.",v->requestRole(),roleState=newState());root.addView(role,lp(-1,-2,0,0,0,10));
        section(root,"ВЫЗОВ «ДЖАРВИС»");LinearLayout wake=card();row(wake,"Фоновое ожидание фразы","Реальный foreground-сервис слушает короткими сегментами и после обнаружения «Джарвис» принимает команду даже поверх другого приложения.",v->toggleWake(),wakeState=newState());wake.addView(button("РАЗРЕШИТЬ РАБОТУ БЕЗ ОГРАНИЧЕНИЙ БАТАРЕИ",v->openBatterySettings()),lp(-1,48,0,10,0,0));root.addView(wake,lp(-1,-2,0,0,0,10));
        section(root,"МИКРОФОН");LinearLayout mic=card();rowSimple(mic,"Разрешение микрофона","Доступ к микрофону для голосового управления.",v->requestMic(),micState);root.addView(mic,lp(-1,-2,0,0,0,10));
        section(root,"ГОЛОС JARVIS");LinearLayout vc=card();rowSimple(vc,"Профиль ответа","Выбор реального русского голоса установленного TTS-движка.",null,voiceState);LinearLayout voices=new LinearLayout(this);voices.setGravity(Gravity.CENTER_VERTICAL);voices.addView(button("МУЖСКОЙ",v->{voice.setGender(JarvisVoiceManager.MALE);voice.speak("Голос JARVIS настроен на мужской профиль.",null);refresh();}),new LinearLayout.LayoutParams(0,48,1));voices.addView(button("ЖЕНСКИЙ",v->{voice.setGender(JarvisVoiceManager.FEMALE);voice.speak("Голос JARVIS настроен на женский профиль.",null);refresh();}),lp(0,48,8,0,0,0));vc.addView(voices,lp(-1,48,0,9,0,0));vc.addView(button("АВТО • ЛУЧШИЙ ДОСТУПНЫЙ",v->{voice.setGender(JarvisVoiceManager.AUTO);voice.speak("Профиль JARVIS переключён в автоматический режим.",null);refresh();}),lp(-1,48,0,8,0,0));vc.addView(button("НАСТРОЙКИ СИНТЕЗА РЕЧИ ANDROID",v->open("com.android.settings.TTS_SETTINGS")),lp(-1,48,0,8,0,0));root.addView(vc,lp(-1,-2,0,0,0,10));
        section(root,"СИСТЕМНЫЕ РАЗДЕЛЫ");addSetting(root,"ГОЛОСОВОЙ ВВОД ANDROID",Settings.ACTION_VOICE_INPUT_SETTINGS);addSetting(root,"УВЕДОМЛЕНИЯ JARVIS",Settings.ACTION_APP_NOTIFICATION_SETTINGS);addSetting(root,"РАЗРЕШЕНИЯ JARVIS",null);addSetting(root,"ТОЧНЫЕ БУДИЛЬНИКИ И НАПОМИНАНИЯ",Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM);addSetting(root,"ОПТИМИЗАЦИЯ БАТАРЕИ",Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);addSetting(root,"НАСТРОЙКИ ЭКРАНА",Settings.ACTION_DISPLAY_SETTINGS);addSetting(root,"BLUETOOTH",Settings.ACTION_BLUETOOTH_SETTINGS);addSetting(root,"WI-FI",Settings.ACTION_WIFI_SETTINGS);
        TextView foot=txt("JARVIS не подменяет системные настройки. Кнопки ведут в соответствующие разделы Android, а голосовые функции используют реальные службы ОС.",11);foot.setTextColor(MUTED);foot.setLineSpacing(0,1.18f);root.addView(foot,lp(-1,-2,0,12,0,0));sc.addView(root);setContentView(sc);refresh();
    }
    private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(14),dp(15),dp(14));c.setBackground(bg(BORDER,SUR,22));return c;}
    private void row(LinearLayout c,String title,String desc,View.OnClickListener click,TextView state){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);TextView t=txt(title,14);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setMaxLines(2);t.setEllipsize(android.text.TextUtils.TruncateAt.END);tx.addView(t,new LinearLayout.LayoutParams(0,dp(30),1));TextView d=txt(desc,11);d.setTextColor(MUTED);d.setMaxLines(3);d.setEllipsize(android.text.TextUtils.TruncateAt.END);tx.addView(d,new LinearLayout.LayoutParams(0,dp(58),1));r.addView(tx,new LinearLayout.LayoutParams(0,dp(90),1));r.addView(state,lp(92,34,10,0,0,0));c.addView(r);c.addView(button("ОТКРЫТЬ / ИЗМЕНИТЬ",click),lp(-1,48,0,10,0,0));}
    private void rowSimple(LinearLayout c,String title,String desc,View.OnClickListener click,TextView state){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.addView(txt(title,14),new LinearLayout.LayoutParams(0,28,1));TextView d=txt(desc,11);d.setTextColor(MUTED);d.setMaxLines(2);tx.addView(d,new LinearLayout.LayoutParams(0,38,1));r.addView(tx,new LinearLayout.LayoutParams(0,66,1));r.addView(state,lp(92,34,10,0,0,0));c.addView(r);if(click!=null)c.addView(button("РАЗРЕШИТЬ / ИЗМЕНИТЬ",click),lp(-1,48,0,9,0,0));}
    private TextView newState(){TextView v=txt("—",10);v.setGravity(Gravity.CENTER);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setSingleLine(true);return v;}
    private void section(LinearLayout root,String s){TextView v=txt(s,10);v.setTextColor(CYAN);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setLetterSpacing(.11f);root.addView(v,lp(-1,22,2,6,0,4));}
    private void addSetting(LinearLayout root,String label,String action){root.addView(button(label,v->{if(action==null)openAppSettings();else open(action);}),lp(-1,48,0,0,0,7));}

    private void requestRole(){if(Build.VERSION.SDK_INT>=29){try{RoleManager rm=getSystemService(RoleManager.class);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_ASSISTANT)){if(!rm.isRoleHeld(RoleManager.ROLE_ASSISTANT)){startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_ASSISTANT),41);}else refresh();return;}}catch(Throwable ignored){}}open(Settings.ACTION_VOICE_INPUT_SETTINGS);}
    private void requestMic(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ);else openAppSettings();}
    private void toggleWake(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ);getSharedPreferences("jarvis",0).edit().putBoolean("wake_pending",true).apply();return;}boolean on=getSharedPreferences("jarvis",0).getBoolean("wake_enabled",false);getSharedPreferences("jarvis",0).edit().putBoolean("wake_enabled",!on).apply();Intent i=new Intent(this,JarvisWakeWordService.class);try{if(!on){if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}else stopService(i);}catch(Throwable e){getSharedPreferences("jarvis",0).edit().putBoolean("wake_enabled",false).apply();}refresh();}
    private void openBatterySettings(){try{startActivity(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+getPackageName())));}catch(Throwable e){open(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS);}}
    private void refresh(){if(roleState==null)return;boolean role=JarvisVoiceInteractionService.isActive(this);roleState.setText(role?"АКТИВЕН":"НЕ ВЫБРАН");roleState.setTextColor(role?GREEN:MUTED);boolean wake=getSharedPreferences("jarvis",0).getBoolean("wake_enabled",false);wakeState.setText(wake?"ВКЛЮЧЕН":"ВЫКЛЮЧЕН");wakeState.setTextColor(wake?GREEN:MUTED);boolean mic=Build.VERSION.SDK_INT<23||checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;micState.setText(mic?"РАЗРЕШЁН":"НЕТ");micState.setTextColor(mic?GREEN:RED);String g=voice==null?JarvisVoiceManager.AUTO:voice.getGender();voiceState.setText(JarvisVoiceManager.MALE.equals(g)?"МУЖСКОЙ":JarvisVoiceManager.FEMALE.equals(g)?"ЖЕНСКИЙ":"АВТО");voiceState.setTextColor(CYAN);}
    private void open(String action){try{Intent i=new Intent(action);if(Settings.ACTION_APP_NOTIFICATION_SETTINGS.equals(action)&&Build.VERSION.SDK_INT>=26)i.putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());if(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM.equals(action))i.setData(Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Throwable e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}
    private void openAppSettings(){Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS);i.setData(Uri.parse("package:"+getPackageName()));startActivity(i);}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&getSharedPreferences("jarvis",0).getBoolean("wake_pending",false)){getSharedPreferences("jarvis",0).edit().putBoolean("wake_pending",false).putBoolean("wake_enabled",true).apply();try{Intent i=new Intent(this,JarvisWakeWordService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Throwable ignored){}}refresh();}
    @Override protected void onResume(){super.onResume();immersive();refresh();}
    @Override protected void onDestroy(){if(voice!=null)voice.shutdown();super.onDestroy();}
}
